const redis = createClient({ url: process.env.REDIS_URL });
await redis.connect();

async function revokeToken(tokenId: string, expiresInMs: number) {
  await redis.setex(
    `revoked:${tokenId}`,
    Math.ceil(expiresInMs / 1000),
    '1'
  );
}

async function isTokenRevoked(tokenId: string): Promise<boolean> {
  const result = await redis.get(`revoked:${tokenId}`);
  return result === '1';
}

async function revokeRefreshToken(userId: string, familyId: string) {
  const tokens = await RefreshToken.find({ userId, familyId, revoked: false });
  const pipeline = redis.multi();

  for (const token of tokens) {
    pipeline.setex(`revoked:${token.jti}`, 86400, '1');
    token.revoked = true;
    await token.save();
  }

  await pipeline.exec();
}

app.post('/api/auth/logout', async (req, res) => {
  const accessToken = req.headers.authorization?.split(' ')[1];
  const refreshToken = req.cookies.refreshToken;

  if (accessToken) {
    const decoded = jwt.decode(accessToken) as { jti?: string; exp?: number };
    if (decoded?.jti && decoded?.exp) {
      const ttl = decoded.exp - Math.floor(Date.now() / 1000);
      await redis.setex(`revoked:${decoded.jti}`, ttl, '1');
    }
  }

  if (refreshToken) {
    const hashedToken = crypto.createHash('sha256').update(refreshToken).digest('hex');
    const storedToken = await RefreshToken.findOne({ token: hashedToken });

    if (storedToken && !storedToken.revoked) {
      storedToken.revoked = true;
      await storedToken.save();

      await RefreshToken.updateMany(
        { familyId: storedToken.familyId, revoked: false },
        { $set: { revoked: true } }
      );
    }
  }

  res.clearCookie('refreshToken', {
    httpOnly: true,
    secure: true,
    sameSite: 'strict'
  });

  res.status(204).send();
});

async function authenticate(req: Request, res: Response, next: NextFunction) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ message: 'Missing token' });
  }

  const token = authHeader.split(' ')[1];

  try {
    const decoded = jwt.verify(token, process.env.ACCESS_SECRET!) as { jti: string; sub: string };

    const isRevoked = await redis.get(`revoked:${decoded.jti}`);
    if (isRevoked) {
      return res.status(401).json({ message: 'Token revoked' });
    }

    req.user = { id: decoded.sub };
    next();
  } catch (err) {
    return res.status(401).json({ message: 'Invalid token' });
  }
}
